/**
 * @suppress
 */
public object FfiConverterTypeWalletHandle: FfiConverter<WalletHandle, Long> {
    override fun lower(value: WalletHandle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): WalletHandle {
        return WalletHandle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): WalletHandle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WalletHandle) = 8UL

    override fun write(value: WalletHandle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Plain view of an address's on-chain state. Mirrors
 * [`AddressInfo`] but with foreign-function-safe primitives only.
 */
data class AddressInfoRecord (
    var `totalReceivedSat`: kotlin.ULong
    , 
    var `finalBalanceSat`: kotlin.ULong
    , 
    var `nTx`: kotlin.ULong
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAddressInfoRecord: FfiConverterRustBuffer<AddressInfoRecord> {
    override fun read(buf: ByteBuffer): AddressInfoRecord {
        return AddressInfoRecord(
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: AddressInfoRecord) = (
            FfiConverterULong.allocationSize(value.`totalReceivedSat`) +
            FfiConverterULong.allocationSize(value.`finalBalanceSat`) +
            FfiConverterULong.allocationSize(value.`nTx`)
    )

    override fun write(value: AddressInfoRecord, buf: ByteBuffer) {
            FfiConverterULong.write(value.`totalReceivedSat`, buf)
            FfiConverterULong.write(value.`finalBalanceSat`, buf)
            FfiConverterULong.write(value.`nTx`, buf)
    }
}



/**
 * Result of [`WalletHandle::ms_create_address`] (Phase 15, spec
 * «Принято (2026-09-02): полный surface»; v0.3 adds the P2WSH and
 * P2TR script-path forms): the fixed quorum address plus the
 * canonical redeem script (hex) it was built from. The address is
 * fixed by the `(N, M, keys)` tuple (ОВ-13) and encoded per the
 * selected form.
 */
data class MsAddressRecord (
    /**
     * The quorum address: `3…` (P2SH), `bc1q…` (P2WSH) or `bc1p…`
     * (P2TR script-path, bech32m v1).
     */
    var `address`: kotlin.String
    , 
    /**
     * Canonical redeem script, BIP-67-sorted, hex-encoded: the bare
     * `OP_m ‖ keys ‖ OP_n ‖ OP_CHECKMULTISIG` script for
     * p2sh/p2wsh (R-MS-3/R-MS-4), the CHECKSIGADD tapscript for
     * p2tr (R-MS-7 — different bytes for the same key set; the
     * field name is unchanged for binding stability, spec
     * «Multi-sig» / FFI).
     */
