/**
 * Flat error type exposed across the FFI boundary.
 *
 * Variants are spelled out so the foreign side can pattern-match by
 * name; the inner `String` carries the wallet- or net-level detail.
 * `From<WalletError>` and `From<NetError>` map every internal
 * failure to the most relevant variant.
 */
sealed class YubtcException(message: String): kotlin.Exception(message) {
        
        class EmptySeed(message: String) : YubtcException(message)
        
        class PrivKey(message: String) : YubtcException(message)
        
        class AddressDecode(message: String) : YubtcException(message)
        
        class TxBuild(message: String) : YubtcException(message)
        
        class TxSign(message: String) : YubtcException(message)
        
        class Psbt(message: String) : YubtcException(message)
        
        class Network(message: String) : YubtcException(message)
        
        class Unsupported(message: String) : YubtcException(message)
        
        class Invalid(message: String) : YubtcException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<YubtcException> {
        override fun lift(error_buf: RustBuffer.ByValue): YubtcException = FfiConverterTypeYubtcError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeYubtcError : FfiConverterRustBuffer<YubtcException> {
    override fun read(buf: ByteBuffer): YubtcException {
        
            return when(buf.getInt()) {
            1 -> YubtcException.EmptySeed(FfiConverterString.read(buf))
            2 -> YubtcException.PrivKey(FfiConverterString.read(buf))
            3 -> YubtcException.AddressDecode(FfiConverterString.read(buf))
            4 -> YubtcException.TxBuild(FfiConverterString.read(buf))
            5 -> YubtcException.TxSign(FfiConverterString.read(buf))
            6 -> YubtcException.Psbt(FfiConverterString.read(buf))
            7 -> YubtcException.Network(FfiConverterString.read(buf))
            8 -> YubtcException.Unsupported(FfiConverterString.read(buf))
            9 -> YubtcException.Invalid(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: YubtcException): ULong {
        return 4UL
    }

    override fun write(value: YubtcException, buf: ByteBuffer) {
        when(value) {
            is YubtcException.EmptySeed -> {
                buf.putInt(1)
                Unit
            }
            is YubtcException.PrivKey -> {
                buf.putInt(2)
                Unit
            }
            is YubtcException.AddressDecode -> {
                buf.putInt(3)
                Unit
            }
            is YubtcException.TxBuild -> {
                buf.putInt(4)
                Unit
            }
            is YubtcException.TxSign -> {
                buf.putInt(5)
                Unit
            }
            is YubtcException.Psbt -> {
                buf.putInt(6)
                Unit
            }
            is YubtcException.Network -> {
                buf.putInt(7)
                Unit
            }
            is YubtcException.Unsupported -> {
                buf.putInt(8)
                Unit
            }
            is YubtcException.Invalid -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
